200	import com.loja.api.PaymentRequest;
201	import com.loja.models.Enums;
202	import com.loja.models.Order;
203	import com.loja.models.OrderItem;
204	
205	import java.sql.SQLException;
206	import java.time.Instant;
207	
208	public class PaymentService {
209	    private static final long PAYMENT_TIMEOUT_MS = 48 * 60 * 60 * 1000;
210	
211	    public static class PaymentResult {
212	        public String error;
213	        public int httpStatus;
214	        public Order order;
215	        public boolean success;
216	
217	        public PaymentResult(String error, int httpStatus) {
218	            this.error = error;
219	            this.httpStatus = httpStatus;
220	            this.success = false;
221	        }
222	
223	        public PaymentResult(Order order) {
224	            this.order = order;
225	            this.success = true;
226	        }
227	    }
228	
229	    public static PaymentResult processPayment(String orderId, PaymentRequest paymentReq) throws SQLException {
230	        Order order = OrderService.getOrder(orderId);
231	        if (order == null) {
232	            return new PaymentResult("ORDER_NOT_FOUND", 404);
233	        }
234	
235	        if (paymentReq.transactionId == null || paymentReq.transactionId.isEmpty() ||
236	            paymentReq.paidAt == null || paymentReq.paidAt.isEmpty()) {
237	            return new PaymentResult("INVALID_ORDER", 422);
238	        }
239	
240	        if (order.status != Enums.OrderStatus.AWAITING_PAYMENT) {
241	            if (OrderService.isPaymentDuplicate(orderId, paymentReq.transactionId)) {
242	                return new PaymentResult(order);
243	            }
244	            return new PaymentResult("OPERATION_NOT_ALLOWED", 409);
245	        }
246	
247	        Instant paidAt = Instant.parse(paymentReq.paidAt);
248	        Instant createdAt = order.createdAt;
249	        long timeDiffMs = paidAt.toEpochMilli() - createdAt.toEpochMilli();
250	
251	        if (timeDiffMs > PAYMENT_TIMEOUT_MS) {
252	            OrderService.updateOrderStatus(orderId, Enums.OrderStatus.CANCELLED);
253	            String cpf = OrderService.getCustomerCpf(orderId);
254	            NotificationService.createNotification(cpf, Enums.NotificationType.ORDER_CANCELLED, orderId);
255	            return new PaymentResult("ORDER_EXPIRED", 409);
256	        }
257	
258	        for (OrderItem item : order.items) {
259	            if (ProductService.getProduct(item.sku).stock < item.quantity) {
260	                OrderService.updateOrderStatus(orderId, Enums.OrderStatus.CANCELLED);
261	                String cpf = OrderService.getCustomerCpf(orderId);
262	                NotificationService.createNotification(cpf, Enums.NotificationType.ORDER_CANCELLED, orderId);
263	                return new PaymentResult("INSUFFICIENT_STOCK", 409);
264	            }
265	        }
266	
267	        for (OrderItem item : order.items) {
268	            ProductService.updateStock(item.sku, -item.quantity);
269	        }
270	
271	        String cpf = OrderService.getCustomerCpf(orderId);
272	        CustomerService.updateCreditBalance(cpf, order.summary.nextPurchaseCredit);
273	
274	        OrderService.recordPayment(orderId, paymentReq.transactionId, paidAt);
275	        OrderService.updateOrderStatus(orderId, Enums.OrderStatus.PAID);
276	
277	        NotificationService.createNotification(cpf, Enums.NotificationType.PAYMENT_APPROVED, orderId);
278	
279	        return new PaymentResult(OrderService.getOrder(orderId));
280	    }
281	}
